import * as THREE from 'three';
import { init, gl, scene, camera, controls } from './init/init';

import vertexShader from './shaders/vertex.js';
import fragmentShader from './shaders/fragment.js';
import { GUI } from './init/lil-gui.module.min';
import './style.css';

init();

let gui = new GUI();

const torus = new THREE.Mesh(
  new THREE.TorusGeometry(1, 0.3, 100, 100),
  new THREE.ShaderMaterial({
    vertexShader,
    fragmentShader,
    side: THREE.DoubleSide,
    transparent: true,
    depthWrite: false,
    uniforms: {
      uTime: { value: 0 },
      uResolution: { value: new THREE.Vector2() },
      uDisplace: { value: 2 },
      uSpread: { value: 1.2 },
      uNoise: { value: 16 },
    },
  })
);

scene.add(torus);

gui
  .add(torus.material.uniforms.uDisplace, 'value', 0, 2, 0.1)
  .name('displacement');
gui.add(torus.material.uniforms.uSpread, 'value', 0, 2, 0.1).name('spread');
gui.add(torus.material.uniforms.uNoise, 'value', 10, 25, 0.1).name('noise');

const clock = new THREE.Clock();

// Interactive background bubble follower
const interBubble = document.querySelector('.interactive');
let curX = 0;
let curY = 0;
let tgX = 0;
let tgY = 0;

window.addEventListener('mousemove', (event) => {
  tgX = event.clientX;
  tgY = event.clientY;
});

window.addEventListener('resize', () => {
  gl.setSize(window.innerWidth, window.innerHeight);
});

let animate = () => {
  const elapsedTime = clock.getElapsedTime();
  torus.material.uniforms.uTime.value = elapsedTime;
  torus.rotation.z = Math.sin(elapsedTime) / 4 + elapsedTime / 20 + 5;

  if (interBubble) {
    curX += (tgX - curX) / 20;
    curY += (tgY - curY) / 20;
    interBubble.style.transform = `translate(${Math.round(curX)}px, ${Math.round(curY)}px)`;
  }

  // Render directly — no EffectComposer so alpha is fully preserved
  gl.render(scene, camera);
  controls.update();
  requestAnimationFrame(animate);
};
animate();

